const BASE = 'http://localhost:8080/api';

export const loginApi = (employeeId, password) =>
  fetch(`${BASE}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ employeeId, password }),
  });

export const createAccountApi = (data) =>
  fetch(`${BASE}/accounts`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });

export const depositApi = (data) =>
  fetch(`${BASE}/transactions/deposit`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });

export const getAccountsApi = () => fetch(`${BASE}/accounts`);
export const getTransactionsApi = () => fetch(`${BASE}/transactions`);
